-- Migration 009: Seed Textos de Impressão
-- Cria os textos interpretativos para os números de Impressão (1 a 9, 11 e 22).

INSERT INTO public.interpretacoes (numero, tipo, titulo, texto) VALUES
(1, 'pessoal_impressao', 'Impressão 1', 'Transmite a imagem de uma figura imponente, dotada de forte independência, coragem e determinação. Em reuniões ou ambientes sociais, posiciona-se de maneira direta e sem muitos rodeios, exalando um ar de autossuficiência. Pode parecer estar constantemente na defensiva em relação à sua própria imagem, uma vez que a sua persona externa foca fortemente na autoafirmação e no pioneirismo.

À primeira vista, pode passar a ideia de ser alguém solitário ou excessivamente individualista, pois demonstra pouca preocupação com a opinião alheia. Projeta a expectativa de que pode assumir o controle de qualquer situação ou grupo com facilidade. Essa postura incisiva, no entanto, pode ser lida equivocadamente como hostilidade ou distanciamento.

Sua aparência é de solidez e grande autoconfiança. Porém, para um observador menos atento, essa firmeza pode ser rapidamente interpretada como teimosia, arrogância ou até mesmo prepotência diante de opiniões divergentes.

Devido a essa presença magnética e controladora, acaba naturalmente atraindo indivíduos que buscam um líder forte para orientá-los, embora nem sempre você deseje assumir esse fardo na intimidade.

Porém, em se tratando da primeira impressão, que nem sempre se confirma, é no conjunto de todas as caraterísticas da personalidade que se estabelece a verdade comportamental do ser humano, e as expressões de seus talentos – talento oculto, motivação, impressão e expressão.'),

(2, 'pessoal_impressao', 'Impressão 2', 'Transmite a imagem de uma figura gentil, diplomática e discreta. Em ambientes sociais, costuma apresentar-se de maneira suave, preferindo ouvir a falar, e exala uma aura de acolhimento e compreensão. Pode parecer que está sempre em busca de harmonia, evitando atritos e mediando silenciosamente as tensões ao seu redor.

À primeira vista, pode passar a ideia de ser alguém excessivamente dependente ou tímido, pois demonstra uma grande consideração pelas necessidades alheias. Projeta a expectativa de ser um excelente parceiro ou colaborador, alguém com quem se pode contar para apaziguar conflitos. Essa postura receptiva, no entanto, pode ser lida equivocadamente como fraqueza ou falta de iniciativa.

Sua aparência é de tranquilidade e refinamento sutil. Porém, para um observador mais agressivo, essa delicadeza pode ser interpretada como insegurança, passividade ou incapacidade de tomar decisões firmes por conta própria.

Devido a essa presença conciliadora e empática, acaba atraindo frequentemente indivíduos de personalidade mais forte ou dominadora, que buscam apoio, ouvidos atentos e um porto seguro emocional.

Porém, em se tratando da primeira impressão, que nem sempre se confirma, é no conjunto de todas as caraterísticas da personalidade que se estabelece a verdade comportamental do ser humano, e as expressões de seus talentos – talento oculto, motivação, impressão e expressão.'),

(3, 'pessoal_impressao', 'Impressão 3', 'Transmite a imagem de uma figura radiante, comunicativa e cheia de vida. Em reuniões sociais, costuma ser o centro das atenções, apresentando-se com muito charme, eloquência e um senso de humor cativante. Pode parecer que está sempre pronto para uma celebração, exalando otimismo e uma energia contagiante que ilumina o ambiente.

À primeira vista, pode passar a ideia de ser alguém extremamente sociável e descontraído, pois interage com grande facilidade e magnetismo. Projeta a expectativa de ser a alma da festa, alguém capaz de inspirar e animar qualquer grupo. Essa postura extrovertida, no entanto, pode ser lida equivocadamente como futilidade ou dispersão.

Sua aparência é vibrante, jovial e, muitas vezes, ligada à moda ou às artes. Porém, para um observador mais conservador, essa expressividade expansiva pode ser interpretada como vaidade excessiva, exibicionismo ou falta de seriedade.

Devido a essa presença magnética e alegre, acaba atraindo pessoas que buscam diversão, inspiração criativa ou simplesmente alguém que as tire da rotina monótona.

Porém, em se tratando da primeira impressão, que nem sempre se confirma, é no conjunto de todas as caraterísticas da personalidade que se estabelece a verdade comportamental do ser humano, e as expressões de seus talentos – talento oculto, motivação, impressão e expressão.'),

(4, 'pessoal_impressao', 'Impressão 4', 'Transmite a imagem de uma figura séria, estruturada, confiável e conservadora. Em reuniões ou ambientes sociais, posiciona-se de maneira formal e cautelosa, exalando um ar de disciplina e pragmatismo. Pode parecer estar sempre focado nos deveres e nas regras, demonstrando um perfil prático que valoriza a organização acima de tudo.

À primeira vista, pode passar a ideia de ser alguém rígido ou de poucas palavras, pois demonstra pouca inclinação para frivolidades. Projeta a expectativa de ser um excelente executor, alguém capaz de assumir tarefas árduas e entregar resultados sólidos. Essa postura metódica, no entanto, pode ser lida equivocadamente como frieza ou falta de imaginação.

Sua aparência é de estabilidade, limpeza e austeridade. Porém, para um observador de espírito livre, essa solidez pode ser interpretada como teimosia severa, limitação de pensamento ou uma mentalidade excessivamente tradicional.

Devido a essa presença constante e responsável, acaba naturalmente atraindo indivíduos que precisam de ordem, de bases seguras ou de alguém para organizar o caos de suas próprias vidas.

Porém, em se tratando da primeira impressão, que nem sempre se confirma, é no conjunto de todas as caraterísticas da personalidade que se estabelece a verdade comportamental do ser humano, e as expressões de seus talentos – talento oculto, motivação, impressão e expressão.'),

(5, 'pessoal_impressao', 'Impressão 5', 'Transmite a imagem de uma figura dinâmica, inquieta, moderna e versátil. Em ambientes sociais, apresenta-se de forma magnética e não convencional, exalando um ar de quem está sempre em busca da próxima grande aventura. Pode parecer desafiador ou provocativo, demonstrando um perfil ágil que não se prende a regras estabelecidas.

À primeira vista, pode passar a ideia de ser alguém indomável ou instável, pois demonstra uma curiosidade voraz por interações variadas. Projeta a expectativa de ser uma pessoa vanguardista, capaz de trazer novidades e quebrar paradigmas. Essa postura imprevisível, no entanto, pode ser lida equivocadamente como irresponsabilidade ou falta de foco.

Sua aparência é geralmente arrojada, acompanhando as tendências de forma original ou exibindo um toque de rebeldia. Porém, para um observador mais metódico, essa necessidade de movimento contínuo pode ser interpretada como superficialidade ou inconstância.

Devido a essa presença eletrizante e adaptável, acaba atraindo pessoas que buscam emoção, inovação e que desejam se libertar das amarras da própria rotina.

Porém, em se tratando da primeira impressão, que nem sempre se confirma, é no conjunto de todas as caraterísticas da personalidade que se estabelece a verdade comportamental do ser humano, e as expressões de seus talentos – talento oculto, motivação, impressão e expressão.'),

(6, 'pessoal_impressao', 'Impressão 6', 'Transmite a imagem de uma figura acolhedora, harmoniosa, elegante e com traços maternais ou paternais. Em reuniões sociais, apresenta-se com grande senso estético e cortesia, exalando uma aura de conforto e responsabilidade afetiva. Pode parecer que está sempre pronto para cuidar, nutrir ou embelezar o ambiente ao seu redor.

À primeira vista, pode passar a ideia de ser o conselheiro do grupo, pois demonstra uma preocupação genuína com o bem-estar coletivo. Projeta a expectativa de ser alguém justo e equilibrado, capaz de resolver conflitos domésticos ou comunitários. Essa postura zelosa, no entanto, pode ser lida equivocadamente como intromissão ou controle sufocante.

Sua aparência é de beleza clássica, bom gosto e simetria. Porém, para um observador mais independente, essa necessidade de manter a paz e a perfeição pode ser interpretada como moralismo, perfeccionismo excessivo ou forte apego às aparências.

Devido a essa presença protetora e afetuosa, acaba naturalmente atraindo indivíduos que buscam colo, conselhos ou pessoas que precisam de alguém para organizar as suas vidas emocionais.

Porém, em se tratando da primeira impressão, que nem sempre se confirma, é no conjunto de todas as caraterísticas da personalidade que se estabelece a verdade comportamental do ser humano, e as expressões de seus talentos – talento oculto, motivação, impressão e expressão.'),

(7, 'pessoal_impressao', 'Impressão 7', 'Transmite a imagem de uma figura misteriosa, intelectual, reservada e observadora. Em ambientes sociais, costuma posicionar-se nos bastidores, analisando o cenário de forma silenciosa e exalando uma aura de profundidade e enigma. Pode parecer distante ou imerso em seus próprios pensamentos, filtrando cuidadosamente quem se aproxima.

À primeira vista, pode passar a ideia de ser alguém inacessível ou aristocrático, pois não demonstra interesse em conversas superficiais. Projeta a expectativa de ser um sábio, um pesquisador ou alguém que detém respostas filosóficas. Essa postura introspectiva, no entanto, pode ser lida equivocadamente como frieza, arrogância ou excentricidade.

Sua aparência é refinada, polida e muitas vezes minimalista. Porém, para um observador mais extrovertido, essa barreira invisível de privacidade pode ser interpretada como antissociabilidade ou desdém pelos assuntos mundanos.

Devido a essa presença enigmática e erudita, acaba atraindo pessoas intrigadas pelo seu mistério, que buscam conselhos profundos ou que desejam desvendar o que se esconde por trás do seu olhar analítico.

Porém, em se tratando da primeira impressão, que nem sempre se confirma, é no conjunto de todas as caraterísticas da personalidade que se estabelece a verdade comportamental do ser humano, e as expressões de seus talentos – talento oculto, motivação, impressão e expressão.'),

(8, 'pessoal_impressao', 'Impressão 8', 'Transmite a imagem de uma figura de poder, autoridade, eficiência e sofisticação. Em reuniões sociais ou de negócios, apresenta-se de forma executiva e assertiva, exalando sucesso material e ambição. Pode parecer estar sempre no controle das circunstâncias, emanando uma confiança que impõe respeito imediato.

À primeira vista, pode passar a ideia de ser alguém estritamente focado em resultados, avaliando as interações pelo seu valor prático. Projeta a expectativa de ser um grande gestor ou líder corporativo, capaz de resolver problemas financeiros com destreza. Essa postura imponente, no entanto, pode ser lida equivocadamente como materialismo exacerbado ou intimidação.

Sua aparência é geralmente impecável, vestindo roupas de alta qualidade que denotam status. Porém, para um observador mais sensível, essa busca por excelência e controle absoluto pode ser interpretada como dureza de coração, ganância ou falta de empatia.

Devido a essa presença magnética de liderança executiva, acaba naturalmente atraindo indivíduos que buscam oportunidades de crescimento, proteção financeira ou que desejam associar-se ao seu sucesso.

Porém, em se tratando da primeira impressão, que nem sempre se confirma, é no conjunto de todas as caraterísticas da personalidade que se estabelece a verdade comportamental do ser humano, e as expressões de seus talentos – talento oculto, motivação, impressão e expressão.'),

(9, 'pessoal_impressao', 'Impressão 9', 'Transmite a imagem de uma figura generosa, carismática, sábia e humanitária. Em ambientes sociais, circula com naturalidade entre diferentes grupos, exalando compaixão e uma mentalidade universal. Pode parecer o conselheiro magnânimo de todos, demonstrando uma tolerância e uma abertura que transcendem preconceitos.

À primeira vista, pode passar a ideia de ser alguém profundamente desapegado ou idealista, pois demonstra intenso interesse nas grandes causas mundiais. Projeta a expectativa de ser um filantropo, um professor inspirador ou alguém pronto para ajudar o mundo. Essa postura altruísta, no entanto, pode ser lida equivocadamente como ingenuidade ou falta de senso prático.

Sua aparência é calorosa e muitas vezes adota um estilo global, despojado ou artístico. Porém, para um observador cínico, essa disposição em perdoar e abraçar a todos de forma incondicional pode ser interpretada como dramatização, falta de limites pessoais ou ilusão utópica.

Devido a essa presença inspiradora e compassiva, acaba atraindo pessoas que precisam de ajuda, cura emocional ou indivíduos que buscam um guia moral para as suas próprias vidas.

Porém, em se tratando da primeira impressão, que nem sempre se confirma, é no conjunto de todas as caraterísticas da personalidade que se estabelece a verdade comportamental do ser humano, e as expressões de seus talentos – talento oculto, motivação, impressão e expressão.'),

(11, 'pessoal_impressao', 'Impressão 11', 'Transmite a imagem de uma figura etérea, magnética, inspirada e altamente intuitiva. Em reuniões sociais, a sua presença costuma ser sentida antes mesmo de ser notada fisicamente, exalando uma aura de eletricidade nervosa ou iluminação espiritual. Pode parecer estar sintonizado em frequências superiores, captando nuances que escapam à maioria.

À primeira vista, pode passar a ideia de ser alguém visionário, místico ou excêntrico, pois o olhar parece focar em um horizonte intangível. Projeta a expectativa de ser um canal de verdades cósmicas, capaz de trazer mensagens reveladoras e inspiradoras. Essa postura transcendente, no entanto, pode ser lida equivocadamente como instabilidade, fanatismo ou extrema desconexão com a realidade.

Sua aparência é fascinante e única, muitas vezes carregando um brilho no olhar que denota profunda sensibilidade. Porém, para um observador puramente pragmático, essa vibração intensa pode ser interpretada como tensão exagerada ou inaptidão para os assuntos terrenos.

Devido a essa presença quase profética, acaba atraindo pessoas em busca de respostas espirituais, luz, inspiração ou orientação para os momentos de crise profunda.

Porém, em se tratando da primeira impressão, que nem sempre se confirma, é no conjunto de todas as caraterísticas da personalidade que se estabelece a verdade comportamental do ser humano, e as expressões de seus talentos – talento oculto, motivação, impressão e expressão.'),

(22, 'pessoal_impressao', 'Impressão 22', 'Transmite a imagem de uma figura grandiosa, genial, prática e capaz de feitos monumentais. Em ambientes sociais, impõe-se de forma natural e estruturada, exalando uma aura de quem está envolvido em projetos que afetam massas ou nações. Pode parecer inatingível pela sua escala colossal de pensamento e capacidade de concretização.

À primeira vista, pode passar a ideia de ser um mestre arquiteto implacável, focado em transformar utopias em estruturas sólidas e governamentais. Projeta a expectativa de ser alguém capaz de orquestrar grandes corporações e causar impacto global. Essa postura épica, no entanto, pode ser lida equivocadamente como tirania ou distanciamento humano devido ao foco extremo.

Sua aparência é de autoridade inquestionável, misturando pragmatismo austero com visão de altíssimo longo prazo. Porém, para um observador voltado aos pequenos detalhes e afetos cotidianos, essa envergadura monumental pode ser interpretada como ambição desmedida ou frieza calculista.

Devido a essa presença arquitetônica e magistral, acaba atraindo indivíduos altamente capacitados, grandes líderes ou pessoas que desejam fazer parte de projetos e transformações históricas.

Porém, em se tratando da primeira impressão, que nem sempre se confirma, é no conjunto de todas as caraterísticas da personalidade que se estabelece a verdade comportamental do ser humano, e as expressões de seus talentos – talento oculto, motivação, impressão e expressão.')

ON CONFLICT (numero, tipo) 
DO UPDATE SET 
  titulo = EXCLUDED.titulo,
  texto = EXCLUDED.texto;
